/**
 * bls12-381-pairing.ts - Toy Bilinear Pairing Properties Model
 *
 * ---------------------------------------------------------------------------
 * What it does
 * ---------------------------------------------------------------------------
 * BLS12-381 provides a bilinear pairing e from two elliptic-curve groups to a
 * target group, satisfying e(aP, bQ) = e(P, Q)^(ab). This module reproduces
 * that exact algebraic property in a tiny multiplicative group: take p = 101,
 * the subgroup of order q = 5 generated by h = 2^20 mod 101, and define
 * e(h^a, h^b) = h^(ab mod q). The map is bilinear, symmetric, and nondegenerate,
 * so every identity a real pairing satisfies can be checked by hand here. It is
 * a teaching model of the pairing equations only: there is no BLS12-381 curve,
 * no extension field, no hashing to curve, and no production security.
 *
 * ---------------------------------------------------------------------------
 * Complexity
 *   Time:  O(log q) modular multiplications for one pairing evaluation
 *   Space: O(1) field elements
 *
 * ---------------------------------------------------------------------------
 * Visualization mapping
 * ---------------------------------------------------------------------------
 *   - Bars show the two group elements, the pairing value, and the property
 *     checks for bilinearity, symmetry, and nondegeneracy.
 */

import type { AlgorithmModule, EntityState, VisualEntity, VisualFrame } from "@/types";

const P = 101;
const Q = 5;
const REAL_G = 2;
const H = 95; // 2^20 mod 101, a generator of the order-5 subgroup.

interface PairingInput {
    a?: number;
    b?: number;
}

function mod(value: number): number {
    return ((value % P) + P) % P;
}

function pow(base: number, exp: number): number {
    let result = 1;
    let b = mod(base);
    let e = exp;
    while (e > 0) {
        if (e & 1) {
            result = mod(result * b);
        }
        b = mod(b * b);
        e = Math.floor(e / 2);
    }
    return result;
}

/** The toy pairing: e(h^a, h^b) = h^(ab mod q). */
function pairing(a: number, b: number): number {
    return pow(H, ((a * b) % Q + Q) % Q);
}

function makeBars(values: Record<string, number>, phase: number, ok: boolean): VisualEntity[] {
    const labels = ["p", "q", "h", "a", "b", "P=h^a", "Q=h^b", "e(P,Q)", "e(h,h)", "bilinear", "symmetric"];
    return labels.map((label, index) => {
        const state: EntityState =
            phase >= 4 ? (label === "bilinear" || label === "symmetric" ? (ok ? "sorted" : "error") : "visited")
            : phase >= 3 && label === "e(P,Q)" ? "highlight"
            : phase >= 2 && (label === "P=h^a" || label === "Q=h^b") ? "comparing"
            : "idle";
        const value = values[label] ?? 0;
        return {
            id: `bar-${index}`,
            type: "bar" as const,
            label: `${label}=${value}`,
            value,
            state,
            x: 0,
            y: 0,
            width: 0,
            height: 0,
            metadata: { index, role: label },
        };
    });
}

/** Demonstrate pairing bilinearity in the order-5 toy subgroup. */
function* run(input: unknown): Generator<VisualFrame, void, unknown> {
    const task = (input as PairingInput | null) ?? {};
    const a = typeof task.a === "number" ? ((Math.trunc(task.a) % Q) + Q) % Q : 2;
    const b = typeof task.b === "number" ? ((Math.trunc(task.b) % Q) + Q) % Q : 3;

    const Pval = pow(H, a);
    const Qval = pow(H, b);
    const ePQ = pairing(a, b);
    const eHH = pairing(1, 1);
    const nonDegenerate = eHH !== 1;

    const P2 = mod(Pval * Pval);
    const leftBilinear = pairing((2 * a) % Q, b);
    const rightBilinear = mod(ePQ * ePQ);
    const bilinear = leftBilinear === rightBilinear;
    const eQP = pairing(b, a);
    const symmetric = ePQ === eQP;
    const ok = bilinear && symmetric && nonDegenerate;

    const values: Record<string, number> = {
        p: P,
        q: Q,
        h: H,
        a,
        b,
        "P=h^a": Pval,
        "Q=h^b": Qval,
        "e(P,Q)": ePQ,
        "e(h,h)": eHH,
        bilinear: bilinear ? 1 : 0,
        symmetric: symmetric ? 1 : 0,
    };

    let step = 0;
    yield {
        stepNumber: step,
        entities: makeBars(values, 0, ok),
        edges: [],
        description: `Toy pairing over the order-${Q} subgroup of the group modulo ${P}; h = ${H}.`,
        codeLineNumber: 0,
        layout: "array",
        meta: { p: P, q: Q, g: REAL_G, h: H, a, b, ok: false },
    };
    step += 1;

    yield {
        stepNumber: step,
        entities: makeBars(values, 1, ok),
        edges: [],
        description: `Group elements: P = h^a = ${Pval}, Q = h^b = ${Qval} in the multiplicative subgroup.`,
        codeLineNumber: 2,
        layout: "array",
        meta: { p: P, q: Q, g: REAL_G, h: H, a, b, Pval, Qval, ok: false },
    };
    step += 1;

    yield {
        stepNumber: step,
        entities: makeBars(values, 3, ok),
        edges: [],
        description: `Pairing value e(P,Q) = h^(a*b mod q) = ${ePQ}; e(h,h) = ${eHH} so the map is nondegenerate.`,
        codeLineNumber: 4,
        layout: "array",
        meta: { p: P, q: Q, g: REAL_G, h: H, a, b, Pval, Qval, ePQ, eHH, nonDegenerate, ok: false },
    };
    step += 1;

    yield {
        stepNumber: step,
        entities: makeBars(values, 4, ok),
        edges: [],
        description: `Bilinearity: e(P^2,Q) = ${leftBilinear} equals e(P,Q)^2 = ${rightBilinear}; symmetry gives e(Q,P) = ${eQP}.`,
        codeLineNumber: 5,
        layout: "array",
        meta: { p: P, q: Q, g: REAL_G, h: H, a, b, Pval, Qval, ePQ, eHH, leftBilinear, rightBilinear, eQP, bilinear, symmetric, nonDegenerate, ok: false },
    };
    step += 1;

    yield {
        stepNumber: step,
        entities: makeBars(values, 4, ok),
        edges: [],
        description: ok
            ? `Done: bilinearity, symmetry, and nondegeneracy all hold in this toy model.`
            : `Done: at least one pairing property failed.`,
        codeLineNumber: 6,
        layout: "array",
        meta: { p: P, q: Q, g: REAL_G, h: H, a, b, Pval, Qval, ePQ, eHH, leftBilinear, rightBilinear, eQP, bilinear, symmetric, nonDegenerate, ok },
    };
}

/** The toy pairing module. */
const module: AlgorithmModule = {
    education: {
        intuition:
            "A pairing is a function that turns multiplication in the exponent into multiplication in a target group: applying it to aP and bQ gives the same result as exponentiating e(P,Q) by a times b. That single property is what lets pairing-based systems verify equations involving secret exponents. This toy uses the order-5 subgroup of the integers modulo 101, where the pairing is just exponent multiplication, so the property can be checked exactly with small numbers.",
        invariants: [
            "Every group element lies in the order-q subgroup generated by h.",
            "The pairing is defined by e(h^a, h^b) = h^(a*b mod q).",
            "Bilinearity means e(P^k, Q) = e(P, Q)^k for every integer k.",
        ],
        correctness:
            "With P = h^a and Q = h^b, the pairing returns h^(ab). Computing P squared gives h^(2a), so e(P squared, Q) = h^(2ab), while squaring the pairing gives (h^(ab))^2 = h^(2ab); the two are identical, proving bilinearity in the subgroup. Exponents commute under multiplication so e(P,Q) = e(Q,P), and e(h,h) = h is not the identity, so the map is nondegenerate. Every identity is exact in this small field.",
        complexityRationale:
            "One pairing evaluation is a modular exponentiation with exponent below q, costing O(log q) multiplications. The demo stores a fixed number of field elements, so space is constant. A real BLS12-381 pairing instead performs Miller loop and final exponentiation on large elliptic-curve extension fields.",
        uses: [
            "Understanding the bilinearity equation behind BLS signatures",
            "A teaching model for pairing-based verifiers and aggregations",
            "Comparing toy group identities with real pairing costs",
        ],
        references: [
            "Boneh and Franklin, Identity-Based Encryption from the Weil Pairing, 2001",
            "Barreto, Lynn and Scott, Constructing Elliptic Curves with Prescribed Embedding Degrees, 2002",
        ],
        workedExample:
            "Modulo 101 the order-5 subgroup is generated by h = 95. With a = 2 and b = 3, P = h squared and Q = h cubed. The pairing e(P,Q) = h^6 mod 5 = h^1 = 95. Squaring P gives h^4 and e(P squared, Q) = h^(4*3 mod 5) = h^2, which equals e(P,Q) squared, so bilinearity holds; swapping a and b leaves the value unchanged, so the pairing is symmetric.",
    },
    id: "bls12-381-pairing",
    name: "BLS12-381 Pairing (Toy Properties Model)",
    category: "cryptography-security",
    complexity: { time: "O(log q)", space: "O(1)" },
    defaultInput: { a: 2, b: 3 },
    visualType: "array",
    run,
    pseudocode: [
        "choose a prime p and a subgroup of prime order q with generator h",
        "read exponents a and b and form P = h^a and Q = h^b",
        "define the pairing as h raised to a*b mod q",
        "evaluate e(P,Q) and confirm e(h,h) is not the identity",
        "check e(P^2,Q) equals e(P,Q)^2",
        "check e(P,Q) equals e(Q,P)",
        "done: report the pairing value and property verdicts",
    ],
};

export default module;
